export function isEInvoiceRejection(
  message: string | null | undefined,
): boolean {
  if (!message) return false;
  return message.includes(REJECTION_PREFIX);
}

/**
 * Extracts code, details and (best-effort) line number from the
 * pipeline-hook rejection message. Robust against:
 *   • em-dash ("—") *or* ASCII dash ("-") between code and details
 *   • optional 400-prefix from FellowHTTPException
 *   • multiple "line N" mentions (returns the *last* one — that's the
 *     failure column from lxml's parse error string)
 */
export function parseEInvoiceMessage(
  message: string,
): ParsedEInvoiceMessage | null {
  if (!message) return null;
  const idx = message.indexOf(REJECTION_PREFIX);
  if (idx === -1) return null;
  const tail = message.slice(idx + REJECTION_PREFIX.length).trim();
  // tail looks like "<CODE> — <details>" or "<CODE> - <details>"
  const sepMatch = tail.match(/^([\w-]+)\s*[—-]\s*([\s\S]+)$/);
  if (!sepMatch) {
    // No separator — treat whole tail as details, code unknown.
    return { code: 'UNKNOWN', details: tail, lineNumber: null };
  }
  const code = sepMatch[1];
  const details = sepMatch[2].trim();

  // "line N" inside the details — pick the last occurrence so lxml's
  // "Premature end of data in tag ID line 5, line 6, column 1" yields
  // 6 (the failing column), which is what the user wants highlighted.
  let lineNumber: number | null = null;
  const lineMatches = [...details.matchAll(/\bline\s+(\d+)\b/gi)];
  if (lineMatches.length > 0) {
    const last = lineMatches[lineMatches.length - 1][1];
    lineNumber = Number(last);
    if (!Number.isFinite(lineNumber) || lineNumber <= 0) lineNumber = null;
  }

  return { code, details, lineNumber };
}

export function layerForCode(code: string): EInvoiceLayer {
  for (const [pattern, layer] of CODE_PREFIX_TO_LAYER) {
    if (pattern.test(code)) return layer;
  }
  // Default: L1 — the first stage that produces non-prefix-matching codes
  // is well-formedness, and a complete-unknown code is safest classified
  // here so the UI still renders something.
  return 'L1';
}

export function explainEInvoiceFinding(
  message: string,
): EInvoiceFindingExplanation | null {
  const parsed = parseEInvoiceMessage(message);
  if (!parsed) return null;
  const layer = layerForCode(parsed.code);
  const codeKeys =
    CODE_TO_KEYS[parsed.code] ?? LAYER_FALLBACK_KEYS[layer];

  return {
    ...parsed,
    layer,
    layerLabelKey: LAYER_TO_LABEL_KEY[layer],
    ...codeKeys,
  };
}
