<template>
  <div class="einvoice-xml-viewer" data-test="einvoice-xml-viewer">
    <div class="xml-viewer-header">
      <q-icon name="mdi:file-xml-box" size="20px" class="q-mr-xs" />
      <span class="xml-viewer-filename">{{ filename || 'document.xml' }}</span>
      <q-space />
      <q-btn
        flat
        dense
        size="sm"
        icon="content_copy"
        :title="$t('copy')"
        @click="copyToClipboard"
        data-test="einvoice-xml-copy"
      />
      <q-btn
        flat
        dense
        size="sm"
        icon="open_in_new"
        :title="$t('open_in_new_tab')"
        :href="rawUrl"
        target="_blank"
        rel="noopener"
        data-test="einvoice-xml-open-raw"
      />
    </div>

    <div v-if="loading" class="xml-viewer-state">
      <q-spinner color="primary" size="32px" />
      <div class="q-mt-sm text-grey-7">{{ $t('loading') }}</div>
    </div>

    <div v-else-if="loadError" class="xml-viewer-state text-red-7">
      <q-icon name="error_outline" size="32px" />
      <div class="q-mt-sm">{{ loadError }}</div>
    </div>

    <div v-else class="xml-viewer-body">
      <pre
        class="xml-viewer-pre"
        ref="preRef"
        data-test="einvoice-xml-pre"
      ><span
        v-for="line in lines"
        :key="line.number"
        :class="['xml-line', { 'xml-line-error': line.number === errorLine }]"
        :data-test="line.number === errorLine ? 'einvoice-xml-error-line' : undefined"
        :ref="(el) => registerLineRef(line.number, el)"
      ><span class="xml-line-num">{{ line.number }}</span><span class="xml-line-content" v-html="line.html"></span>
</span></pre>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { DOC2API_URL } from 'src/pages/APIs';
import { useImageAuth } from 'src/composables/useImageAuth';

interface RenderedLine {
  number: number;
  html: string;
}

const ENTITY_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ENTITY_MAP[c] || c);
}

/**
 * Lightweight XML highlighter — no extra dep.
 * Colours: tag-name, attribute, attribute-value, comment, processing-instruction.
 * The input must be raw XML; we escape first, then re-inject span markers
 * by replacing the escaped angle-bracket sequences.
 */
function highlightXmlLine(line: string): string {
  const escaped = escapeHtml(line);

  return escaped
    .replace(
      /(&lt;!--[\s\S]*?--&gt;)/g,
      '<span class="xml-comment">$1</span>',
    )
    .replace(
      /(&lt;\?[\s\S]*?\?&gt;)/g,
      '<span class="xml-pi">$1</span>',
    )
    .replace(
      /(&lt;\/?)([\w:.-]+)/g,
      '$1<span class="xml-tag">$2</span>',
    )
    .replace(
      /([\w:.-]+)=(&quot;[^&]*?&quot;)/g,
      '<span class="xml-attr">$1</span>=<span class="xml-value">$2</span>',
    );
}

export default defineComponent({
  name: 'EInvoiceXmlViewer',
  props: {
    docId: { type: String, required: true },
    filename: { type: String, default: '' },
    /** When set, scroll to and highlight this line (1-based) */
    errorLine: { type: Number, default: 0 },
  },
  data() {
    return {
      raw: '' as string,
      loading: true,
      loadError: '' as string,
      lineRefs: {} as Record<number, HTMLElement | null>,
    };
  },
  computed: {
    rawUrl(): string {
      return `${DOC2API_URL}/resource/document/${this.docId}/${this.docId}.xml?download=false&${this.tokenQueryParam}`;
    },
    lines(): RenderedLine[] {
      if (!this.raw) return [];
      return this.raw.split(/\r?\n/).map((line, i) => ({
        number: i + 1,
        html: highlightXmlLine(line) || '&nbsp;',
      }));
    },
  },
  watch: {
    docId: {
      immediate: true,
      handler() {
        this.fetchXml();
      },
    },
    errorLine() {
      this.scrollToErrorLine();
    },
  },
  methods: {
    registerLineRef(num: number, el: any) {
      this.lineRefs[num] = el as HTMLElement | null;
    },
    async fetchXml() {
      this.loading = true;
      this.loadError = '';
      try {
        await this.refreshTokenParam();
        const res = await fetch(this.rawUrl);
        if (!res.ok) {
          throw new Error(`HTTP ${res.status}`);
        }
        const text = await res.text();
        if (text.trimStart().startsWith('{') && text.includes('"success":false')) {
          throw new Error(this.$t('einvoice_xml_not_available'));
        }
        this.raw = text;
        await this.$nextTick();
        this.scrollToErrorLine();
      } catch (e: any) {
        this.loadError = e?.message || String(e);
      } finally {
        this.loading = false;
      }
    },
    scrollToErrorLine() {
      if (!this.errorLine) return;
      const el = this.lineRefs[this.errorLine];
      if (el && typeof el.scrollIntoView === 'function') {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    },
    async copyToClipboard() {
      try {
        await navigator.clipboard.writeText(this.raw);
        notify.success(this.$t('copied_to_clipboard'));
      } catch {
        notify.error(this.$t('copy_failed'));
      }
    },
  },
  setup() {
    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    return {
      tokenQueryParam,
      refreshTokenParam,
      preRef: ref<HTMLElement | null>(null),
    };
  },
});
</script>

