<template>
  <div class="col-6">
    <!-- Error Header -->
    <div class="export-error-header q-px-lg q-pb-md">
      <div>
        <h2 class="error-title">
          <q-icon name="error" size="28px" color="red-6" />
          {{ isExportError ? $t('export_error').toUpperCase() : $t('error').toUpperCase() }}
        </h2>
      </div>
      <q-btn
        v-if="isExportError"
        unelevated
        color="primary"
        no-caps
        @click="$emit('go-to-field-validation')"
        :label="$t('fields_validation')"
      />
    </div>

    <!-- Scrollable Content Area -->
    <div class="scrollable-content">
      <!-- Error Details Section (always shown) -->
      <div class="q-px-lg">
        <div class="export-card card-failed">
          <div class="export-card-header">
            <div class="export-info">
              <div class="export-name">
                <q-icon
                  name="close"
                  color="red-6"
                  size="18px"
                  class="q-mr-xs"
                />
                {{ getStepDisplayName(failedStep) }}
              </div>
              <div class="export-type">{{ getStepDescription(failedStep) }}</div>
              <div v-if="isExportError && totalSteps > 0" class="export-type">
                {{ $t('export_failed_at_step') }} {{ timelineFailedStepIndex }} {{ $t('of') }} {{ totalSteps }}
              </div>
            </div>
            <span class="status-badge badge-failed">
              {{ $t('failed') }}
            </span>
          </div>

          <!--
            BOL-423: When the rejection came from the e-invoice validator
            (BOL-421 hook), surface a *user-friendly* explanation card
            BEFORE the raw technical message. Non-technical users need to
            see WHICH check rejected the invoice and WHAT to do next; the
            raw `XML-PARSE — Premature end of data` line is kept below in a
            collapsible "Technical details" section.
          -->
          <div
            v-if="einvoiceFinding"
            class="einvoice-explain-card q-mb-md"
            data-test="einvoice-explain-card"
          >
            <div class="einvoice-explain-header">
              <q-icon name="mdi:shield-alert" size="22px" class="q-mr-sm" />
              <div class="einvoice-explain-headings">
                <div class="einvoice-explain-eyebrow" data-test="einvoice-layer-label">
                  {{ $t('einvoice_rejected_by_layer_eyebrow') }}
                  <q-chip
                    dense
                    square
                    color="red-1"
                    text-color="red-9"
                    class="q-ml-xs einvoice-layer-chip"
                  >
                    {{ einvoiceFinding.layer }} · {{ $t(einvoiceFinding.layerLabelKey) }}
                  </q-chip>
                </div>
                <div class="einvoice-explain-title" data-test="einvoice-explain-title">
                  {{ $t(einvoiceFinding.titleKey) }}
                </div>
              </div>
              <q-space />
              <q-chip
                dense
                square
                color="grey-2"
                text-color="grey-9"
                class="einvoice-code-chip"
                data-test="einvoice-code-chip"
              >
                <code>{{ einvoiceFinding.code }}</code>
              </q-chip>
            </div>

            <div class="einvoice-explain-body" data-test="einvoice-explain-body">
              {{ $t(einvoiceFinding.explanationKey) }}
            </div>

            <div class="einvoice-explain-action" data-test="einvoice-explain-action">
              <q-icon name="mdi:lightbulb-on-outline" class="q-mr-xs" />
              <strong>{{ $t('einvoice_next_step') }}:</strong>
              {{ $t(einvoiceFinding.actionKey) }}
            </div>

            <div
              v-if="einvoiceFinding.lineNumber"
              class="einvoice-explain-line-hint"
              data-test="einvoice-explain-line-hint"
            >
              <q-icon name="mdi:format-list-numbered" class="q-mr-xs" />
              {{ $t('einvoice_line_hint', { line: einvoiceFinding.lineNumber }) }}
            </div>

            <div
              v-if="validationReport"
              class="validation-cta q-mt-md"
              data-test="error-validation-cta"
            >
              <q-btn
                unelevated
                no-caps
                color="primary"
                icon="mdi:shield-search"
                :label="$t('validation_view_details_button')"
                data-test="error-open-validation-panel"
                @click="validationPanelOpen = true"
              />
              <span class="validation-cta-hint q-ml-sm text-caption text-grey-7">
                {{ $t('validation_view_details_hint') }}
              </span>
            </div>
          </div>

          <!-- Error Details -->
          <div class="error-details-box">
            <div
              v-if="einvoiceFinding"
              class="error-technical-toggle q-mb-sm"
              data-test="einvoice-technical-toggle"
            >
              <q-btn
                flat
                dense
                no-caps
                size="sm"
                :icon="technicalDetailsOpen ? 'expand_less' : 'expand_more'"
                :label="$t('einvoice_show_technical_details')"
                color="grey-7"
                @click="technicalDetailsOpen = !technicalDetailsOpen"
              />
            </div>
            <div
              v-show="!einvoiceFinding || technicalDetailsOpen"
              class="error-details-content"
              data-test="einvoice-technical-block"
            >
              <div v-if="message">
                <strong>{{ $t('message') }}:</strong> {{ message }}
              </div>
              <div v-if="exception" class="error-exception">
                <strong>{{ $t('exception') }}:</strong> {{ exception }}
              </div>
            </div>

            <!--
              BOL-418-followup fallback: legacy rejections without an
              e-invoice classification still show the "View validation
              details" CTA when the API attached a structured
              validation_report. With an einvoiceFinding above, the same
              CTA is rendered next to the explanation card instead.
            -->
            <div
              v-if="validationReport && !einvoiceFinding"
              class="validation-cta q-mt-md"
              data-test="error-validation-cta-legacy"
            >
              <q-btn
                unelevated
                no-caps
                color="primary"
                icon="mdi:shield-search"
                :label="$t('validation_view_details_button')"
                data-test="error-open-validation-panel"
                @click="validationPanelOpen = true"
              />
              <span class="validation-cta-hint q-ml-sm text-caption text-grey-7">
                {{ $t('validation_view_details_hint') }}
              </span>
            </div>
          </div>
        </div>
      </div>

      <!-- BOL-418 ValidationReportPanel — only mounts when there's a report. -->
      <ValidationReportPanel
        v-if="validationReport"
        v-model="validationPanelOpen"
        :report="validationReport"
      />

      <!-- Export Timeline Section (shown for export errors) -->
      <div v-if="isExportError" class="export-timeline-section">

        <!-- Export Execution Timeline -->
        <div class="timeline-section q-px-lg">
          <h3 class="timeline-title">{{ $t('export_execution_timeline') }}</h3>

          <div class="timeline-items">
            <div
              v-for="(exportItem, index) in exportExecutions"
              :key="exportItem.id || index"
              class="timeline-item"
            >
              <!-- Step Number Circle -->
              <div class="timeline-step-column">
                <div
                  class="step-circle"
                  :class="{
                    'step-success': exportItem.status === 'success',
                    'step-failed': exportItem.status === 'failed',
                    'step-skipped': exportItem.status === 'skipped',
                    'step-pending': exportItem.status === 'pending',
                  }"
                >
                  {{ index + 1 }}
                </div>
                <div
                  v-if="index < exportExecutions.length - 1"
                  class="timeline-connector"
                ></div>
              </div>

              <!-- Export Card -->
              <div class="timeline-content">
                <div
                  class="export-card"
                  :class="{
                    'card-success': exportItem.status === 'success',
                    'card-failed': exportItem.status === 'failed',
                    'card-skipped': exportItem.status === 'skipped',
                  }"
                >
                  <div class="export-card-header">
                    <div class="export-info">
                      <div class="export-name">
                        <q-icon
                          :name="getTimelineStatusIcon(exportItem.status)"
                          :color="getTimelineStatusColor(exportItem.status)"
                          size="18px"
                          class="q-mr-xs"
                        />
                        {{ exportItem.title }}
                      </div>
                      <div class="export-type">{{ exportItem.exportType }}</div>
                    </div>
                    <span
                      class="status-badge"
                      :class="{
                        'badge-success': exportItem.status === 'success',
                        'badge-failed': exportItem.status === 'failed',
                        'badge-skipped': exportItem.status === 'skipped',
                      }"
                    >
                      {{ getTimelineStatusLabel(exportItem.status) }}
                    </span>
                  </div>

                  <div class="export-card-meta">
                    <template v-if="exportItem.status === 'success'">
                      <div>{{ $t('executed') }}: {{ formatDateTime(exportItem.executedAt) }}</div>
                      <div v-if="exportItem.duration">{{ $t('duration') }}: {{ exportItem.duration }}</div>
                    </template>
                    <template v-else-if="exportItem.status === 'failed'">
                      <div>{{ $t('attempted') }}: {{ formatDateTime(exportItem.executedAt) }}</div>
                      <div v-if="exportItem.duration">{{ $t('duration') }}: {{ exportItem.duration }}</div>
                    </template>
                    <template v-else-if="exportItem.status === 'skipped'">
                      <div>{{ $t('not_executed_due_to_previous_failure') }}</div>
                    </template>
                  </div>

                  <!-- Error Details for Failed Export -->
                  <div v-if="exportItem.status === 'failed' && exportItem.error" class="error-details-box">
                    <div class="error-details-title">{{ $t('error_details') }}:</div>
                    <div class="error-details-content">
                      <div v-if="exportItem.error.code">
                        <strong>{{ $t('code') }}:</strong> {{ exportItem.error.code }}
                      </div>
                      <div v-if="exportItem.error.message">
                        <strong>{{ $t('message') }}:</strong> {{ exportItem.error.message }}
                      </div>
                      <div v-if="exportItem.error.exception" class="error-exception">
                        <strong>{{ $t('exception') }}:</strong> {{ exportItem.error.exception }}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Info Banner -->
        <div class="info-banner q-mx-lg">
          <q-icon name="info" size="20px" color="primary" class="q-mr-sm" />
          <div class="info-text">
            <strong>{{ $t('what_happens_restart_export') }}</strong><br />
            {{ $t('restart_export_description') }}
          </div>
        </div>
      </div>

      <!-- Action Buttons -->
      <div class="error-actions q-mx-md row">
        <div class="col-4 q-pr-sm">
          <q-btn
            @click="$emit('restart-document')"
            :loading="restarting"
            color="primary"
            unelevated
            no-caps
            class="full-width"
          >
            <q-icon name="refresh" size="16px" class="q-mr-xs" />
            {{ isExportError ? $t('restart_export_from_failed') : $t('restart_processing') }}
          </q-btn>
        </div>

        <div class="col-4 q-px-sm">
          <q-btn
            @click="$emit('view-doc-flow')"
            color="blue-grey-6"
            outline
            no-caps
            class="full-width"
          >
            <q-icon name="account_tree" size="16px" class="q-mr-xs" />
            {{ $t('view_docflow') }}
          </q-btn>
        </div>

        <div class="col-4 q-pl-sm">
          <q-btn @click="copyErrorInfo()" flat color="grey-7" no-caps class="full-width">
            <q-icon name="content_copy" size="14px" class="q-mr-xs" />
            {{ $t('copy_details') }}
          </q-btn>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, type PropType } from 'vue';
import { exportApiService } from 'src/services';
import type { ExportExecution } from 'src/pages/Settings/Components/ListOfValuesRedesign/types';
import ValidationReportPanel from 'src/pages/Components/ValidationReportPanel.vue';
import type { ValidationReport } from 'src/types/validationReport';
import {
  explainEInvoiceFinding,
  type EInvoiceFindingExplanation,
} from 'src/utils/einvoice/findingExplainer';

export default defineComponent({
  name: 'ErrorDetailsPanel',
  components: { ValidationReportPanel },
  props: {
    message: {
      type: String,
      required: true,
    },
    exception: {
      type: String,
      required: true,
    },
    errorDetails: {
      type: Object,
      default: null,
    },
    /** BOL-421-B / BOL-418-followup: when the API surfaces a
     *  structured ValidationReport on `/get_errors`, the panel opens
     *  on demand. Null when the failure isn't validator-driven. */
    validationReport: {
      type: Object as PropType<ValidationReport | null>,
      default: null,
    },
    isExportError: {
      type: Boolean,
      default: false,
    },
    restarting: {
      type: Boolean,
      default: false,
    },
    docId: {
      type: String,
      required: true,
    },
    filename: {
      type: String,
      default: '',
    },
  },
  emits: ['go-to-field-validation', 'restart-document', 'view-doc-flow'],
  data() {
    return {
      exportExecutions: [] as ExportExecution[],
      loading: false,
      validationPanelOpen: false,
      technicalDetailsOpen: false,
    };
  },
  computed: {
    /**
     * BOL-423: Parse the e-invoice rejection message into a structured
     * explanation when applicable. Returns null for non-validator
     * errors so the legacy raw-message UI keeps working.
     */
    einvoiceFinding(): EInvoiceFindingExplanation | null {
      const combined = `${this.message ?? ''} ${this.exception ?? ''}`;
      return explainEInvoiceFinding(combined);
    },
    failedStep(): string {
      if (this.errorDetails && this.errorDetails.failed_step) {
        return this.errorDetails.failed_step.name;
      }

      if (!this.message && !this.exception) return 'Unknown';

      const errorText = (this.message + ' ' + this.exception).toLowerCase();

      if (
        errorText.includes('doc_type') ||
        errorText.includes('classif') ||
        errorText.includes('template')
      ) {
        return 'classify';
      }
      if (
        errorText.includes('ocr') ||
        errorText.includes('text') ||
        errorText.includes('extraction')
      ) {
        return 'ocr';
      }
      if (errorText.includes('barcode') || errorText.includes('qr')) {
        return 'barcode_extraction';
      }
      if (errorText.includes('field') || errorText.includes('validation')) {
        return 'field_extraction';
      }
      if (errorText.includes('table')) {
        return 'table_extraction';
      }
      if (errorText.includes('export') || errorText.includes('infor')) {
        return 'export';
      }
      if (errorText.includes('import') || errorText.includes('upload')) {
        return 'import';
      }

      return 'processing';
    },
    timelineFailedStepIndex(): number {
      const index = this.exportExecutions.findIndex((e: ExportExecution) => e.status === 'failed');
      return index >= 0 ? index + 1 : 0;
    },
    totalSteps(): number {
      return this.exportExecutions.length;
    },
  },
  watch: {
    docId() {
      this.loadExportExecutions();
    },
    isExportError() {
      this.loadExportExecutions();
    },
  },
  mounted() {
    this.loadExportExecutions();
  },
  methods: {
    getStepDisplayName(stepName: string): string {
      const stepNames: { [key: string]: string } = {
        import: 'Document Import',
        ocr: 'Text Recognition (OCR)',
        classify: 'Classification',
        barcode_extraction: 'Barcode Extraction',
        field_extraction: 'Field Extraction',
        table_extraction: 'Table Extraction',
        validation: 'Validation',
        export: 'Export',
        processing: 'Document Processing',
      };
      return (
        stepNames[stepName] ||
        stepName.charAt(0).toUpperCase() + stepName.slice(1)
      );
    },
    getStepIcon(stepName: string): string {
      const stepIcons: { [key: string]: string } = {
        import: 'file_upload',
        ocr: 'text_fields',
        classify: 'category',
        barcode_extraction: 'qr_code_scanner',
        field_extraction: 'edit_note',
        table_extraction: 'table_chart',
        validation: 'verified_user',
        export: 'file_download',
        processing: 'settings',
      };
      return stepIcons[stepName] || 'close';
    },
    getStepDescription(stepName: string): string {
      const descriptions: { [key: string]: string } = {
        import: 'Document upload and initial processing',
        ocr: 'Converting document images to searchable text',
        classify: 'Detecting document type and template',
        barcode_extraction: 'Scanning for barcodes and QR codes',
        field_extraction: 'Extracting data from document fields',
        table_extraction: 'Processing table data',
        validation: 'Validating extracted data',
        export: 'Exporting to external systems',
        processing: 'General document processing',
      };
      return descriptions[stepName] || 'Processing step encountered an error';
    },
    mapExportStatus(status: string): 'success' | 'failed' | 'skipped' | 'pending' {
      const statusMap: Record<string, 'success' | 'failed' | 'skipped' | 'pending'> = {
        'SUCCESS': 'success',
        'FAIL': 'failed',
        'SKIPPED': 'skipped',
        'PENDING': 'pending',
      };
      return statusMap[status] || 'pending';
    },
    parseErrorMessage(response: string | null): string {
      if (!response) return '';

      if (response.trim().startsWith('<!') || response.trim().startsWith('<html')) {
        const titleMatch = response.match(/<title[^>]*>([^<]+)<\/title>/i);
        if (titleMatch && titleMatch[1]) {
          return titleMatch[1].trim();
        }

        const bodyMatch = response.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
        if (bodyMatch && bodyMatch[1]) {
          const plainText = bodyMatch[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
          if (plainText) {
            return plainText.substring(0, 200) + (plainText.length > 200 ? '...' : '');
          }
        }

        return 'HTML Error Response';
      }

      return response;
    },
    async loadExportExecutions() {
      if (!this.docId || !this.isExportError) return;

      this.loading = true;
      try {
        const response = await exportApiService.getExportLogs(this.docId, {
          includeSkipped: true,
          includeDeleted: false,
          limit: 100,
          offset: 0,
        });
        if (response && response.export_logs) {
          this.exportExecutions = response.export_logs.map((log: any) => ({
            id: log.export_config_id,
            title: log.title || 'Export',
            exportType: log.export_application || log.export_method || 'Unknown',
            status: this.mapExportStatus(log.export_status),
            executedAt: log.exported_on,
            duration: undefined,
            error: log.export_status === 'FAIL' ? {
              code: log.export_response_status_code,
              message: this.parseErrorMessage(log.export_response),
            } : undefined,
          }));
        }
      } catch (err) {
        logError('Error loading export executions:', err);
        if (this.message || this.exception) {
          this.exportExecutions = [{
            id: '1',
            title: 'Export',
            exportType: 'Unknown',
            status: 'failed',
            error: {
              message: this.message,
              exception: this.exception,
            },
          }];
        }
      } finally {
        this.loading = false;
      }
    },
    getTimelineStatusIcon(status: string): string {
      const icons: { [key: string]: string } = {
        success: 'check',
        failed: 'close',
        skipped: 'remove',
        pending: 'schedule',
      };
      return icons[status] || 'help_outline';
    },
    getTimelineStatusColor(status: string): string {
      const colors: { [key: string]: string } = {
        success: 'green-6',
        failed: 'red-6',
        skipped: 'grey-6',
        pending: 'grey-5',
      };
      return colors[status] || 'grey-6';
    },
    getTimelineStatusLabel(status: string): string {
      const labels: { [key: string]: string } = {
        success: 'SUCCESS',
        failed: 'FAILED',
        skipped: 'SKIPPED',
        pending: 'PENDING',
      };
      return labels[status] || status.toUpperCase();
    },
    formatDateTime(dateStr?: string): string {
      if (!dateStr) return '-';
      try {
        const date = new Date(dateStr);
        return date.toLocaleString('de-DE', {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric',
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
        });
      } catch {
        return dateStr;
      }
    },
    copyErrorInfo() {
      // Always include base error info
      let errorInfo = `Error Report:
File: ${this.filename || 'Unknown'}
Failed Step: ${this.getStepDisplayName(this.failedStep)}
Message: ${this.message}
Exception: ${this.exception}
Document ID: ${this.docId}
Timestamp: ${new Date().toISOString()}`;

      // Append export execution details if available
      if (this.isExportError && this.exportExecutions.length > 0) {
        const failedExports = this.exportExecutions.filter((e: ExportExecution) => e.status === 'failed');
        const successExports = this.exportExecutions.filter((e: ExportExecution) => e.status === 'success');
        const skippedExports = this.exportExecutions.filter((e: ExportExecution) => e.status === 'skipped');

        errorInfo += `\n\n--- Export Execution Details ---\n`;
        errorInfo += `Total Exports: ${this.exportExecutions.length}\n`;
        errorInfo += `Failed: ${failedExports.length}, Success: ${successExports.length}, Skipped: ${skippedExports.length}\n`;
        errorInfo += `Failed at Step: ${this.timelineFailedStepIndex} of ${this.totalSteps}\n`;

        this.exportExecutions.forEach((exp: ExportExecution, index: number) => {
          errorInfo += `\n--- Export ${index + 1}: ${exp.title} ---\n`;
          errorInfo += `Type: ${exp.exportType}\n`;
          errorInfo += `Status: ${exp.status.toUpperCase()}\n`;
          if (exp.executedAt) {
            errorInfo += `Executed: ${this.formatDateTime(exp.executedAt)}\n`;
          }
          if (exp.error) {
            if (exp.error.code) errorInfo += `Error Code: ${exp.error.code}\n`;
            if (exp.error.message) errorInfo += `Message: ${exp.error.message}\n`;
            if (exp.error.exception) errorInfo += `Exception: ${exp.error.exception}\n`;
          }
        });
      }

      navigator.clipboard.writeText(errorInfo);
      notify.success('Error details copied to clipboard');
    },
  },
});
</script>

